using Finance.Core;
using System.Data;
using System.Drawing.Printing;
using System.Text.Json;
namespace Finance.Desktop;
internal partial class MainForm
{
    DataTable AllReport(string name,string search){DataTable? all=null;for(int page=0;;page++){var t=engine.Report(name,Ui.Day(from),Ui.Day(to),search,page,10000);all??=t.Clone();foreach(DataRow r in t.Rows)all.ImportRow(r);if(t.Rows.Count<10000)break;}return all!;}
    void ExportReport(string report,string search){using var save=new SaveFileDialog{Filter="Excel workbook|*.xlsx",FileName=report.Replace('/','-')+".xlsx"};if(save.ShowDialog()!=DialogResult.OK)return;var raw=AllReport(report,search);if(File.Exists(save.FileName))File.Delete(save.FileName);using var d=engine.Open();ExcelExport.Write(save.FileName,Value.Text(d.Scalar("SELECT Name FROM Company WHERE Id=1"))+" — "+report+" — "+Value.Date(Ui.Day(from))+" to "+Value.Date(Ui.Day(to)),Engine.DisplayTable(raw));MessageBox.Show("Excel export saved.");}
    void PrintReport(string report,string search){var t=Engine.DisplayTable(AllReport(report,search));var lines=new List<string>{"Period: "+Value.Date(Ui.Day(from))+" to "+Value.Date(Ui.Day(to)),""};foreach(DataRow r in t.Rows){foreach(DataColumn c in t.Columns)if(!string.IsNullOrEmpty(Value.Text(r[c])))lines.Add(c.ColumnName+": "+Value.Text(r[c]));lines.Add("────────────────────────────────────────────────");}Document(report,lines);}
    void ShowDocument(string report,long id,DataRow selected){using var d=engine.Open();var lines=new List<string>();string title=report;
        if(report is "Sales Register" or "Purchase Register"){var r=d.Row("SELECT i.*,p.Name AS PartyName,p.Address AS PartyAddress FROM Invoice i JOIN Party p ON p.Id=i.PartyId WHERE i.Id=@p0",id);title=Value.Text(r["Kind"])+" invoice "+Value.Text(r["Number"]);lines.Add("Date: "+Value.Date((int)Value.Long(r["Day"]))+"   Due: "+Value.Date((int)Value.Long(r["DueDay"])));lines.Add("Party: "+Value.Text(r["PartyName"]));lines.Add(Value.Text(r["PartyAddress"]));lines.Add("Party GSTIN: "+Value.Text(r["PartyGSTIN"])+"   Place of supply: "+Value.Text(r["PlaceOfSupply"]));lines.Add("Reference: "+Value.Text(r["Reference"]));lines.Add(Value.Long(r["Cancelled"])==1?"CANCELLED":r["VoucherId"] is DBNull?"DRAFT":"POSTED");lines.Add("");foreach(DataRow item in d.Table("SELECT * FROM InvoiceLine WHERE InvoiceId=@p0",id).Rows){lines.Add(Value.Text(item["Description"])+" | HSN/SAC: "+Value.Text(item["HSN"]));lines.Add($"Qty {item["Quantity"]} {item["Unit"]} × INR {Value.Display(Value.Long(item["Rate"]))}   Discount INR {Value.Display(Value.Long(item["Discount"]))}");lines.Add($"Taxable {Value.Display(Value.Long(item["Taxable"]))}   GST {item["GSTRate"]}%   CGST {Value.Display(Value.Long(item["CGST"]))}   SGST {Value.Display(Value.Long(item["SGST"]))}   IGST {Value.Display(Value.Long(item["IGST"]))}   Total {Value.Display(Value.Long(item["Total"]))}");lines.Add("");}foreach(var k in new[]{"Taxable","CGST","SGST","IGST","RoundOff","Total"})lines.Add(k+": INR "+Value.Display(Value.Long(r[k])));lines.Add("Remarks: "+Value.Text(r["Remarks"]));}
        else if(report is "Payroll Register" or "Salary Payment Status"){var r=d.Row("SELECT r.Snapshot,p.Day,p.Status,e.Code FROM PayrollRow r JOIN Payroll p ON p.Id=r.PayrollId JOIN Employee e ON e.Id=r.EmployeeId WHERE r.Id=@p0",id);var p=JsonSerializer.Deserialize<PayrollResult>(Value.Text(r["Snapshot"]))!;title="Salary slip • "+p.Name;lines.Add("Employee: "+r["Code"]+"   Period ending: "+Value.Date((int)Value.Long(r["Day"]))+"   "+r["Status"]);lines.Add($"Calendar days: {p.CalendarDays}   Paid Sundays: {p.Sundays}   Eligible: {p.EligibleDays}   Absent: {p.Absent}   Payable: {p.PayableDays}");foreach(var (label,a) in new (string,long)[]{("Monthly salary",p.MonthlySalary),("Earned salary",p.Earned),("Basic",p.Basic),("Allowance",p.Allowance),("OT",p.OT),("Bonus",p.Bonus),("Arrear",p.Arrear),("Other addition",p.OtherAddition),("EPF",p.EPF),("ESIC",p.ESIC),("Advance deduction",p.Advance),("Loan recovery",p.LoanRecovery),("Other deduction",p.OtherDeduction),("Rounding",p.Rounding),("NET PAYABLE",p.Net)})lines.Add(label+": INR "+Value.Display(a));}
        else if(report=="Transaction Register"){var r=d.Row("SELECT * FROM Voucher WHERE Id=@p0",id);title=Value.Text(r["Kind"])+" voucher "+r["Number"];lines.Add("Date: "+Value.Date((int)Value.Long(r["Day"])));lines.Add(Value.Text(r["Narration"]));foreach(DataRow l in d.Table("SELECT a.Name,p.Amount,COALESCE(pt.Name,e.Name,b.Name,'') AS Party FROM Posting p JOIN Account a ON a.Code=p.Account LEFT JOIN Party pt ON pt.Id=p.PartyId LEFT JOIN Employee e ON e.Id=p.EmployeeId LEFT JOIN Bank b ON b.Id=p.BankId WHERE p.VoucherId=@p0",id).Rows){long amount=Value.Long(l["Amount"]);lines.Add((amount>0?"By ":"To ")+l["Name"]+"  "+l["Party"]+"  INR "+Value.Display(Math.Abs(amount)));}if(r["ReversedBy"] is not DBNull)lines.Add("REVERSED");}
        else{var single=selected.Table.Clone();single.ImportRow(selected);var display=Engine.DisplayTable(single);foreach(DataColumn c in display.Columns)lines.Add(c.ColumnName+": "+Value.Text(display.Rows[0][c]));}
        Document(title,lines);
    }
    void Document(string title,List<string> lines)
    {
        using var f=new Form{Text=title,Width=960,Height=750,StartPosition=FormStartPosition.CenterParent};using var d=engine.Open();var co=d.Row("SELECT * FROM Company WHERE Id=1");var all=new List<string>{Value.Text(co["Name"]),Value.Text(co["Address"]),"GSTIN: "+Value.Text(co["GSTIN"]),Value.Text(co["Mobile"])+"  "+Value.Text(co["Email"])+"  "+Value.Text(co["Website"]),"",title,""};all.AddRange(lines);var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Font=new("Consolas",10),Text=string.Join(Environment.NewLine,all)};byte[]? logo=Value.Long(co["ShowLogo"])==1?co["Logo"] as byte[]:null;
        PrintDocument MakePrint(){var doc=new PrintDocument{DocumentName=title};doc.DefaultPageSettings.Margins=new Margins(45,45,45,45);var printLines=new List<string>();using var font=new Font("Segoe UI",10);foreach(string line in all)foreach(string segment in line.Replace("\r","").Split('\n')){if(segment.Length<=95)printLines.Add(segment);else for(int i=0;i<segment.Length;i+=95)printLines.Add(segment.Substring(i,Math.Min(95,segment.Length-i)));}int index=0,page=0;doc.BeginPrint+=(_,_)=>{index=0;page=0;};doc.PrintPage+=(_,e)=>{page++;float y=e.MarginBounds.Top;using var body=new Font("Segoe UI",10);if(logo!=null){using var ms=new MemoryStream(logo);using var img=Image.FromStream(ms);float h=48,w=img.Width*h/img.Height;if(w>150){w=150;h=img.Height*w/img.Width;}float left=Value.Text(co["LogoPosition"]) switch{"Centre"=>e.MarginBounds.Left+(e.MarginBounds.Width-w)/2,"Right"=>e.MarginBounds.Right-w,_=>e.MarginBounds.Left};e.Graphics!.DrawImage(img,left,y,w,h);y+=58;}float height=body.GetHeight(e.Graphics!)+5;while(index<printLines.Count&&y+height<e.MarginBounds.Bottom-25){e.Graphics!.DrawString(printLines[index++],body,Brushes.Black,e.MarginBounds.Left,y);y+=height;}e.Graphics!.DrawString($"Page {page}",body,Brushes.Gray,e.MarginBounds.Left,e.MarginBounds.Bottom);e.HasMorePages=index<printLines.Count;};return doc;}
        var bar=Bar();bar.Dock=DockStyle.Bottom;bar.Controls.Add(Ui.Button("Print preview",()=>{using var doc=MakePrint();using var preview=new PrintPreviewDialog{Document=doc,Width=1050,Height=780};preview.ShowDialog(f);}));bar.Controls.Add(Ui.Button("Print",()=>{using var doc=MakePrint();using var dialog=new PrintDialog{Document=doc,UseEXDialog=true};if(dialog.ShowDialog(f)==DialogResult.OK)doc.Print();}));bar.Controls.Add(Ui.Button("Export PDF",()=>{Value.Require(PrinterSettings.InstalledPrinters.Cast<string>().Contains("Microsoft Print to PDF"),"Enable the built-in Microsoft Print to PDF printer in Windows to export PDF.");using var save=new SaveFileDialog{Filter="PDF document|*.pdf",FileName="Document.pdf"};if(save.ShowDialog()!=DialogResult.OK)return;using var doc=MakePrint();doc.PrinterSettings.PrinterName="Microsoft Print to PDF";doc.PrinterSettings.PrintToFile=true;doc.PrinterSettings.PrintFileName=save.FileName;doc.PrintController=new StandardPrintController();doc.Print();}));f.Controls.Add(text);f.Controls.Add(bar);f.ShowDialog(this);
    }
    void Attachments(string entity,long id){using var f=new Form{Text="Attachments",Width=800,Height=500,StartPosition=FormStartPosition.CenterParent};var grid=Ui.Grid();void Load(){using var d=engine.Open();grid.DataSource=Engine.DisplayTable(d.Table("SELECT Id,Name,SHA256,CreatedUtc AS [Added Time] FROM Attachment WHERE Entity=@p0 AND EntityId=@p1 AND Removed=0",entity,id));}long Selected(){Value.Require(grid.CurrentRow!=null,"Select an attachment.");return Value.Long(grid.CurrentRow!.Cells["Id"].Value);}var bar=Bar();bar.Controls.Add(Ui.Button("Add",()=>{using var open=new OpenFileDialog{Filter="Documents|*.pdf;*.png;*.jpg;*.jpeg;*.txt;*.csv;*.xlsx;*.docx"};if(open.ShowDialog()==DialogResult.OK){engine.Attach(entity,id,System.IO.Path.GetFileName(open.FileName),File.ReadAllBytes(open.FileName));Load();}}));bar.Controls.Add(Ui.Button("Open / preview",()=>{var a=engine.Attachment(Selected());string dir=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"BusinessFinance",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string path=System.IO.Path.Combine(dir,a.Name);File.WriteAllBytes(path,a.Bytes);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});},140));bar.Controls.Add(Ui.Button("Save copy",()=>{var a=engine.Attachment(Selected());using var save=new SaveFileDialog{FileName=a.Name};if(save.ShowDialog()==DialogResult.OK)File.WriteAllBytes(save.FileName,a.Bytes);}));bar.Controls.Add(Ui.Button("Remove",()=>{ReasonDate("Remove attachment",(_,reason)=>engine.RemoveAttachment(Selected(),reason));Load();}));f.Controls.Add(grid);f.Controls.Add(bar);Load();f.ShowDialog(this);}
}
